from rules import solve_versions


def solve(data):
    return solve_versions(
        data['packages'],
        data['roots'],
        data.get('blocked', {}),
        data.get('pins', {}),
        data.get('features', []),
    )

def solve_versions(packages, roots, blocked=None, pins=None, features=None):
    blocked = blocked or {}
    pins = pins or {}
    features = set(features or [])
    names = sorted(packages)
    best_vector = None
    best_versions = None

    def is_acyclic(edges):
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for dependency in edges.get(name, ()):
                if not visit(dependency):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in edges)

    def search(versions, constraints, edges):
        nonlocal best_vector, best_versions

        for name, version in versions.items():
            if name not in packages:
                return
            low, high = constraints[name]
            if not low <= version <= high:
                return

        pending = set(constraints).difference(versions)
        if any(name not in packages for name in pending):
            return

        if not pending:
            if not is_acyclic(edges):
                return
            vector = tuple(versions.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = dict(versions)
            return

        name = min(pending)
        low, high = constraints[name]

        for row in packages[name]:
            version = row['version']
            if not low <= version <= high:
                continue
            if version in blocked.get(name, ()):
                continue
            if name in pins and version != pins[name]:
                continue

            next_versions = dict(versions)
            next_versions[name] = version
            next_constraints = dict(constraints)
            next_edges = dict(edges)
            active_dependencies = []
            valid = True

            for dependency in row['deps']:
                feature = dependency.get('feature')
                if feature and feature not in features:
                    continue

                dep_name = dependency['name']
                dep_low = dependency['min']
                dep_high = dependency['max']
                if dep_name in next_constraints:
                    old_low, old_high = next_constraints[dep_name]
                    dep_low = max(dep_low, old_low)
                    dep_high = min(dep_high, old_high)
                if dep_low > dep_high:
                    valid = False
                    break
                next_constraints[dep_name] = (dep_low, dep_high)
                active_dependencies.append(dep_name)

            if valid:
                next_edges[name] = active_dependencies
                search(next_versions, next_constraints, next_edges)

    constraints = {
        name: (interval[0], interval[1])
        for name, interval in roots.items()
    }
    search({}, constraints, {})

    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
